INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-HER-CONFESSION','Lattafa','Her Confession Eau de Parfum 100 ml','العطور','العطور','عطر يليق بعشاء هادئ أو مناسبة تحبّين فيها شيئًا ناعمًا بطابع دافئ. تبرز القرفة في البداية، ثم يلين حضورها مع الياسمين ومسك الروم ولمسة بخور. وفي النهاية تبقى الفانيلا والمسك مع حلاوة خفيفة من التونكا.','{"nameAr":"لطافة هير كونفشن · أو دو بارفان نسائي 100 مل","tagline":"ياسمين وفانيلا لأمسية هادئة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من القرفة ونفحة ميستيكال","القلب من الياسمين ومسك الروم والبخور والماهونيال","القاعدة من الفانيلا والمسك وحبوب التونكا"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 7.50 د.أ، أقل بـ70% من سعر 25 د.أ المعروض لدى أوسكار للعطور في الأردن في 27 نوفمبر 2026.","en":{"name":"Her Confession Eau de Parfum 100 ml","tagline":"Jasmine and vanilla for a quiet evening","description":"A warm floral for a quiet dinner or a dressed-up evening. Cinnamon leads, then softens into jasmine and tuberose with a touch of incense. Vanilla and musk leave a gentle sweetness with tonka.","benefits":["Cinnamon and a Mystikal accord at the opening","Jasmine, tuberose, incense and Mahonial in the heart","Vanilla, musk and tonka at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. The first batch is priced at 7.50 JOD, 70% below the 25 JOD price listed by Oscar Fragrances in Jordan on 27 November 2026.","size":"100 ml"}}',7500,7500,0,'/media/catalog/TSPF-HER-CONFESSION-97113bb42ff8.webp','https://lattafa.com/product/her-confession/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
