INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-MUSAMAM-WHITE-INTENSE','Lattafa','Musamam White Intense Eau de Parfum 100 ml','العطور','العطور','لليوم الذي تحبّ فيه رائحة مشرقة أولًا ثم أدفأ مع الوقت. يفتح البرغموت والبرتقال العطر بانتعاش خفيف، ثم يظهر جوز الهند والإيلنغ إلى جانب الأمبروكسان. يعطِيه خشب الصندل والجاوي في النهاية نعومة تناسب طلعة نهارية أو لقاءً مسائيًا.','{"nameAr":"لطافة مصمّم وايت إنتنس · أو دو بارفان للجنسين 100 مل","tagline":"بداية حمضية تنتهي بدفء كريمي","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["المقدمة من البرغموت والبرتقال والتوابل","القلب من الإيلنغ وجوز الهند والأمبروكسان","القاعدة من خشب الصندل والجاوي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور. سعر الدفعة الأولى 6.00 د.أ، أقل بـ70% من سعر 20 د.أ المعروض لدى أوسكار للعطور في الأردن في 27 نوفمبر 2026.","en":{"name":"Musamam White Intense Eau de Parfum 100 ml","tagline":"A citrus opening with a creamy, warm finish","description":"A scent for days that start bright and end slow. Bergamot and orange lift the opening, then coconut and ylang-ylang meet ambroxan. Sandalwood and benzoin leave a creamy finish that works for daytime plans or an evening out.","benefits":["Bergamot, orange and spices at the opening","Ylang-ylang, coconut and ambroxan in the heart","Sandalwood and benzoin at the base"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances. The first batch is priced at 6.00 JOD, 70% below the 20 JOD price listed by Oscar Fragrances in Jordan on 27 November 2026.","size":"100 ml"}}',6000,6000,0,'/media/catalog/TSPF-MUSAMAM-WHITE-INTENSE-fc9125df560e.webp','https://lattafa.com/product/musamam-white-intense/','Lattafa',24,1,1) ON CONFLICT(id) DO NOTHING;
